provider "aws" {
  region = var.region

  default_tags {
    tags = local.common_tags
  }
}

resource "aws_athena_workgroup" "this" {
  name = "${var.name_prefix}-athena"
  configuration {
    enforce_workgroup_configuration = true
    result_configuration {
      output_location = "s3://${var.artifacts_bucket_name}/athena-results/"
    }
  }
  tags = var.tags
}

resource "aws_s3_bucket" "audit" {
  bucket        = "${var.name_prefix}-s3-audit-${random_id.suffix.hex}"
  force_destroy = true

  tags = merge(var.tags, {
    Name = "${var.name_prefix}-s3-audit"
  })
}

resource "aws_s3_bucket_policy" "audit" {
  bucket = aws_s3_bucket.audit.id
  policy = data.aws_iam_policy_document.bucket.json
}

resource "aws_cloudtrail" "this" {
  name                          = "${var.name_prefix}-cloudtrail"
  s3_bucket_name                = aws_s3_bucket.audit.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true

  depends_on = [aws_s3_bucket_policy.audit]

  tags = merge(var.tags, {
    Name = "${var.name_prefix}-cloudtrail"
  })
}

resource "aws_cloudtrail" "this" {
  name                          = "${var.name_prefix}-cloudtrail"
  s3_bucket_name                = aws_s3_bucket.audit.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true

  depends_on = [aws_s3_bucket_policy.audit]

  tags = merge(var.tags, {
    Name = "${var.name_prefix}-cloudtrail"
  })
}

resource "aws_cloudtrail" "this" {
  name                          = "${var.name_prefix}-cloudtrail"
  s3_bucket_name                = aws_s3_bucket.audit.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true

  depends_on = [aws_s3_bucket_policy.audit]

  tags = merge(var.tags, {
    Name = "${var.name_prefix}-cloudtrail"
  })
}

data "aws_iam_policy_document" "bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.audit.arn]
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.audit.arn}/AWSLogs/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

